values ('M22602', 2, 'HSK 2 · HSK 3.0 загвар шалгалт №2 (全真模拟)', 60, 52, true, '[{"skill": "listening", "audio_url": "/mock-tests/m22602/listening.mp3", "time_min": 17, "parts": [{"part": 1, "range": [1, 5], "q_type": "match", "desc": "Яриа ↔ зураг"}, {"part": 2, "range": [6, 15], "q_type": "match", "desc": "Харилцан яриа ↔ зураг"}, {"part": 3, "range": [16, 25], "q_type": "choice", "desc": "Харилцан яриа, зөв хариулт сонгох"}]}, {"skill": "reading", "audio_url": null, "time_min": 25, "parts": [{"part": 1, "range": [26, 30], "q_type": "match", "desc": "Өгүүлбэр ↔ зураг"}, {"part": 2, "range": [31, 35], "q_type": "fill_word", "desc": "Үг сонгож нөхөх"}, {"part": 3, "range": [36, 45], "q_type": "match", "desc": "Асуулт ↔ хариулт"}, {"part": 4, "range": [46, 50], "q_type": "choice", "desc": "Богино өгүүлбэр уншиж сонгох"}]}, {"skill": "writing", "audio_url": null, "time_min": 10, "parts": [{"part": 1, "range": [51, 55], "q_type": "match", "desc": "Ханзын дутуу хэсгийг нөхөх"}, {"part": 2, "range": [56, 60], "q_type": "fill_char", "desc": "Пиньинь харж ханз бичих"}]}]'::jsonb, true)
