insert into public.mock_test_questions (test_id, skill, part, q_no, q_type, stem, options, correct_answer, autograde, points, audio_url, image_url, needs_image, tags, explanation_mn, audio_start_sec, audio_end_sec, audio_transcript, tutor_note) values
('M22602','listening',1,1,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m22602/img/q01A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m22602/img/q01B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m22602/img/q01C.webp"}]'::jsonb,'B','auto',1,'/mock-tests/m22602/listening.mp3',null,true,array['sk.listening.match','voc.hsk2','hsk30']::text[],'Багш руу хандаж «这个题我会做» (энэ бодлогыг би бодож чадна) гэж байна. Ангид суугаа сурагчтай зураг B таарна.',91.15,108.32,'老师，这个题我会做。','{"transcript": [{"zh": "老师，这个题我会做。", "pinyin": "lǎoshī, zhège tí wǒ huì zuò.", "mn": "Багш аа, энэ бодлогыг би бодож чадна."}], "key": "这个题我会做", "keyMn": "Энэ бодлогыг би бодож чадна", "why": "Багш руу хандаж «这个题我会做» (энэ бодлогыг би бодож чадна) гэж байна. Ангид суугаа сурагчтай зураг B таарна.", "wrong": {"A": "Зурагт найзууд телевизорын өмнө гараа өргөн баярлаж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй.", "C": "Зурагт нэг хүү номныхоо өмнө эрүүгээ тулан уйтгартай сууж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй."}, "trap": "Сурагч ангид байгаа ч C-д хүү уйтгартай байгаа, «чадна» гэсэн утгатай нийцэхгүй.", "tip": "Хэнтэй, хаана ярьж байгааг (老师 = ангид) эхлээд барь.", "words": [{"zh": "老师", "pinyin": "lǎoshī", "mn": "багш"}, {"zh": "题", "pinyin": "tí", "mn": "бодлого, асуулт"}, {"zh": "会", "pinyin": "huì", "mn": "чадах (сурсан)"}, {"zh": "做", "pinyin": "zuò", "mn": "хийх, бодох"}]}'::jsonb),
('M22602','listening',1,2,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m22602/img/q02A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m22602/img/q02B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m22602/img/q02C.webp"}]'::jsonb,'A','auto',1,'/mock-tests/m22602/listening.mp3',null,true,array['sk.listening.match','voc.hsk2','hsk30']::text[],'«地铁上玩手机、上网» гэдэг нь метрон дээр утас хэрэглэхийг хэлж байна. Метронд хүмүүс утсаа барьж байгаа зураг A таарна.',108.62,139.94,'大家在地铁上可以玩玩手机、上上网。','{"transcript": [{"zh": "大家在地铁上可以玩玩手机、上上网。", "pinyin": "dàjiā zài dìtiě shang kěyǐ wánwan shǒujī, shàngshang wǎng.", "mn": "Метрон дээр хүн бүр утсаа ашиглаж, интернэтээр орж болно."}], "key": "在地铁上玩玩手机", "keyMn": "Метрон дээр утсаа ашиглах", "why": "«地铁上玩手机、上网» гэдэг нь метрон дээр утас хэрэглэхийг хэлж байна. Метронд хүмүүс утсаа барьж байгаа зураг A таарна.", "wrong": {"B": "Зурагт оюутнууд тооцоолуурын өрөөнд сууж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй.", "C": "Зурагт метронд нэг эр сонин уншиж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй."}, "trap": "C-д бас метро байгаа ч тэр хүн сонин уншиж байна, утас биш.", "tip": "Газар (地铁) болон үйлдэл (手机) хоёуланг нь шалга.", "words": [{"zh": "地铁", "pinyin": "dìtiě", "mn": "метро"}, {"zh": "手机", "pinyin": "shǒujī", "mn": "гар утас"}, {"zh": "上网", "pinyin": "shàngwǎng", "mn": "интернэтээр орох"}, {"zh": "玩", "pinyin": "wán", "mn": "тоглох, хөгжилдөх"}]}'::jsonb),
('M22602','listening',1,3,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m22602/img/q03A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m22602/img/q03B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m22602/img/q03C.webp"}]'::jsonb,'A','auto',1,'/mock-tests/m22602/listening.mp3',null,true,array['sk.listening.match','voc.hsk2','hsk30']::text[],'«妈妈做得快多了» гэдэг нь ээж хоол зэргийг хийж байгааг, чи тусалсан болохоор хурдан болсныг хэлнэ. Ээж, хүүхэд хамт хоол хийж буй зураг A таарна.',140.24,167.28,'谢谢！有你帮忙，妈妈做得快多了。','{"transcript": [{"zh": "谢谢！有你帮忙，妈妈做得快多了。", "pinyin": "xièxie! yǒu nǐ bāngmáng, māma zuò de kuài duō le.", "mn": "Баярлалаа! Чи тусалсан болохоор ээж илүү хурдан хийж байна."}], "key": "有你帮忙，妈妈做得快多了", "keyMn": "Чи тусалсан болохоор ээж хурдан хийж байна", "why": "«妈妈做得快多了» гэдэг нь ээж хоол зэргийг хийж байгааг, чи тусалсан болохоор хурдан болсныг хэлнэ. Ээж, хүүхэд хамт хоол хийж буй зураг A таарна.", "wrong": {"B": "Зурагт хос хоёр хүний дугуйгаар зугаалж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй.", "C": "Зурагт хос цэнгэлдэхэд хамт гүйж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй."}, "tip": "Хүн, үйлдлийн хоёрыг (妈妈 + 做) барьвал хангалттай.", "words": [{"zh": "帮忙", "pinyin": "bāngmáng", "mn": "тусалах"}, {"zh": "妈妈", "pinyin": "māma", "mn": "ээж"}, {"zh": "做", "pinyin": "zuò", "mn": "хийх"}, {"zh": "快", "pinyin": "kuài", "mn": "хурдан"}, {"zh": "多了", "pinyin": "duō le", "mn": "хамаагүй илүү"}]}'::jsonb),
('M22602','listening',1,4,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m22602/img/q04A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m22602/img/q04B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m22602/img/q04C.webp"}]'::jsonb,'C','auto',1,'/mock-tests/m22602/listening.mp3',null,true,array['sk.listening.match','voc.hsk2','hsk30']::text[],'«家门口这些花» гэдэг нь гэрийн үүдэн дэх цэцэг. Байшингийн үүдэнд цэцэг ургаж буй зураг C таарна.',167.58,192.72,'我太喜欢家门口这些花了。','{"transcript": [{"zh": "我太喜欢家门口这些花了。", "pinyin": "wǒ tài xǐhuan jiā ménkǒu zhèxiē huā le.", "mn": "Би гэрийнхээ үүдэнд байгаа эдгээр цэцэгт маш их дуртай."}], "key": "家门口这些花", "keyMn": "Гэрийн үүдний эдгээр цэцэг", "why": "«家门口这些花» гэдэг нь гэрийн үүдэн дэх цэцэг. Байшингийн үүдэнд цэцэг ургаж буй зураг C таарна.", "wrong": {"A": "Зурагт эмэгтэй хүүд цэцгийн баглаа өгч байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй.", "B": "Зурагт ширээн дээр ваартай сарнай, дэргэд нь нээлттэй ном байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй."}, "trap": "A, B-д бас цэцэг байгаа ч нэг нь бэлэглэж, нөгөө нь ваартай; «家门口» (үүд) зөвхөн C.", "tip": "Цэцэг гэдгээр нь биш, байршлын үгээр (门口) ялга.", "words": [{"zh": "喜欢", "pinyin": "xǐhuan", "mn": "дуртай"}, {"zh": "家门口", "pinyin": "jiā ménkǒu", "mn": "гэрийн үүд"}, {"zh": "花", "pinyin": "huā", "mn": "цэцэг"}, {"zh": "太…了", "pinyin": "tài…le", "mn": "маш, үнэхээр"}]}'::jsonb),
('M22602','listening',1,5,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m22602/img/q05A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m22602/img/q05B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m22602/img/q05C.webp"}]'::jsonb,'C','auto',1,'/mock-tests/m22602/listening.mp3',null,true,array['sk.listening.match','voc.hsk2','hsk30']::text[],'«一起看电影» нь хамт кино үзнэ гэсэн үг. Хоёр хүн кино театрт суугаа зураг C таарна.',193.02,215.4,'他们经常一起看电影。','{"transcript": [{"zh": "他们经常一起看电影。", "pinyin": "tāmen jīngcháng yìqǐ kàn diànyǐng.", "mn": "Тэд байнга хамт кино үздэг."}], "key": "一起看电影", "keyMn": "Хамт кино үзэх", "why": "«一起看电影» нь хамт кино үзнэ гэсэн үг. Хоёр хүн кино театрт суугаа зураг C таарна.", "wrong": {"A": "Зурагт хос супермаркетад тэргэнцэр түлхэж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй.", "B": "Зурагт хүмүүс номын санд ном уншиж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй."}, "tip": "«看» гэдэг нь «үзэх, уншихаар» хоёуланг хэлдэг тул объектыг (电影) сонс.", "words": [{"zh": "经常", "pinyin": "jīngcháng", "mn": "байнга"}, {"zh": "一起", "pinyin": "yìqǐ", "mn": "хамт"}, {"zh": "看", "pinyin": "kàn", "mn": "үзэх, харах"}, {"zh": "电影", "pinyin": "diànyǐng", "mn": "кино"}]}'::jsonb),
('M22602','listening',2,6,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m22602/img/q06A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m22602/img/q06B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m22602/img/q06C.webp"}, {"key": "D", "text": "", "image_url": "/mock-tests/m22602/img/q06D.webp"}, {"key": "E", "text": "", "image_url": "/mock-tests/m22602/img/q06E.webp"}, {"key": "F", "text": "", "image_url": "/mock-tests/m22602/img/q06F.webp"}]'::jsonb,'B','auto',1,'/mock-tests/m22602/listening.mp3',null,true,array['sk.listening.match','voc.hsk2','hsk30']::text[],'Эр «您慢一点儿，请坐这儿吧» гэж хөгшин хүнд суудал өгч байна. Залуу өвөө эмээд суудал тавьж өгч буй зураг B таарна.',255.36,287.19,'男：您慢一点儿，请坐这儿吧。
女：谢谢你，孩子！','{"transcript": [{"zh": "男：您慢一点儿，请坐这儿吧。", "pinyin": "nán: nín màn yìdiǎnr, qǐng zuò zhèr ba.", "mn": "Эр: Аажуухан, энд суугаарай."}, {"zh": "女：谢谢你，孩子！", "pinyin": "nǚ: xièxie nǐ, háizi!", "mn": "Эм: Баярлалаа, хүү минь!"}], "key": "请坐这儿吧", "keyMn": "Энд суугаарай", "why": "Эр «您慢一点儿，请坐这儿吧» гэж хөгшин хүнд суудал өгч байна. Залуу өвөө эмээд суудал тавьж өгч буй зураг B таарна.", "wrong": {"A": "Зурагт эмэгтэй гудамжинд зам заан зааж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй.", "C": "Зурагт эмч өвчтэй охинтой ярьж байна, ээж нь дэргэд нь; өгөгдсөн өгүүлбэр/яриатай холбоогүй.", "D": "Зурагт охин хөл бөмбөг өшиглөж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй.", "E": "Зурагт хос цонхоор гадаа цас харж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй.", "F": "Зурагт гэр бүл шинэ жилээр бие биедээ мэндчилж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй."}, "trap": "«孩子» гэж эмэгтэй залууг дуудсанаас эмэгтэй нь хөгшин хүн гэдгийг мэднэ.", "tip": "«请坐» сонсвол суудал өгч байгаа дүр зургийг хай.", "words": [{"zh": "慢", "pinyin": "màn", "mn": "удаан"}, {"zh": "请坐", "pinyin": "qǐng zuò", "mn": "суугаарай"}, {"zh": "谢谢", "pinyin": "xièxie", "mn": "баярлалаа"}, {"zh": "孩子", "pinyin": "háizi", "mn": "хүүхэд"}]}'::jsonb),
