('M22602','reading',1,26,'match','你怎么了？可以跟我说说吗？','[{"key": "A", "text": "", "image_url": "/mock-tests/m22602/img/q26A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m22602/img/q26B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m22602/img/q26C.webp"}, {"key": "D", "text": "", "image_url": "/mock-tests/m22602/img/q26D.webp"}, {"key": "E", "text": "", "image_url": "/mock-tests/m22602/img/q26E.webp"}, {"key": "F", "text": "", "image_url": "/mock-tests/m22602/img/q26F.webp"}]'::jsonb,'E','auto',1,null,null,true,array['sk.reading.match','voc.hsk2','hsk30']::text[],'«你怎么了？可以跟我说说吗？» гэдэг нь гунигтай хүнээс асууж, тайвшруулах үг. Ээж гунигтай хүүгээ тэврэн тайвшруулж буй зураг E таарна.',null,null,null,'{"key": "你怎么了？可以跟我说说吗？", "keyMn": "Чамд юу болсон бэ? Надад хэлж болох уу?", "why": "«你怎么了？可以跟我说说吗？» гэдэг нь гунигтай хүнээс асууж, тайвшруулах үг. Ээж гунигтай хүүгээ тэврэн тайвшруулж буй зураг E таарна.", "wrong": {"A": "Зурагт ээж хүүгээ усан санд сэлэхийг сургаж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй.", "B": "Зурагт эмэгтэй дэлгэцийн өмнө ядарч эвшээж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй.", "C": "Зурагт хоёр хүн ажлын цаас харж ярилцаж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй.", "D": "Зурагт залуу сагсан бөмбөг барьж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй.", "F": "Зурагт охин чихэвчтэй гүйлтийн замаар гүйж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй."}, "tip": "Асууж зөөлөн ярьж байвал тайвшруулах дүр зургийг хай.", "words": [{"zh": "怎么了", "pinyin": "zěnme le", "mn": "юу болсон бэ"}, {"zh": "说", "pinyin": "shuō", "mn": "хэлэх"}, {"zh": "可以", "pinyin": "kěyǐ", "mn": "болох"}]}'::jsonb),
('M22602','reading',1,27,'match','你看，这里是不是写错了？我没看懂。','[{"key": "A", "text": "", "image_url": "/mock-tests/m22602/img/q26A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m22602/img/q26B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m22602/img/q26C.webp"}, {"key": "D", "text": "", "image_url": "/mock-tests/m22602/img/q26D.webp"}, {"key": "E", "text": "", "image_url": "/mock-tests/m22602/img/q26E.webp"}, {"key": "F", "text": "", "image_url": "/mock-tests/m22602/img/q26F.webp"}]'::jsonb,'C','auto',1,null,null,true,array['sk.reading.match','voc.hsk2','hsk30']::text[],'«这里是不是写错了？我没看懂» гэдэг нь цаасан дээр бичсэнийг хамт харж байна. Хоёр хүн цаас харж ярилцаж буй зураг C таарна.',null,null,null,'{"key": "这里是不是写错了？", "keyMn": "Энд буруу бичсэн биш үү?", "why": "«这里是不是写错了？我没看懂» гэдэг нь цаасан дээр бичсэнийг хамт харж байна. Хоёр хүн цаас харж ярилцаж буй зураг C таарна.", "wrong": {"A": "Зурагт ээж хүүгээ усан санд сэлэхийг сургаж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй.", "B": "Зурагт эмэгтэй дэлгэцийн өмнө ядарч эвшээж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй.", "D": "Зурагт залуу сагсан бөмбөг барьж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй.", "E": "Зурагт ээж гунигтай хүүгээ тэврэн тайвшруулж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй.", "F": "Зурагт охин чихэвчтэй гүйлтийн замаар гүйж байна; өгөгдсөн өгүүлбэр/яриатай холбоогүй."}, "words": [{"zh": "写错", "pinyin": "xiěcuò", "mn": "буруу бичих"}, {"zh": "看懂", "pinyin": "kàndǒng", "mn": "уншаад ойлгох"}, {"zh": "是不是", "pinyin": "shì bu shì", "mn": "...биз дээ?"}, {"zh": "这里", "pinyin": "zhèli", "mn": "энд"}]}'::jsonb),
